    cols = [[0,1], [2,3], [4,6]]

    output = []
    for ri in range(3):
        row = []
        for ci in range(3):
            freq = {}
            has_only_01 = True
            for r in range(rows[ri][0], rows[ri][1] + 1):
                for c in range(cols[ci][0], cols[ci][1] + 1):
                    v = grid[r][c]
                    freq[v] = freq.get(v, 0) + 1
                    if v not in [0, 1]:
                        has_only_01 = False

